/* Local classic OCR (OEM 0), explicit image preparation and rule-based topic search. */
(()=>{
 'use strict';
 const T=window.SCHOOL_SCAN_TOOLS;let busy=false,stop=false,worker=null,loader=null;
 let language='rus+eng',message='',quality=[],workGrade=state.grade,workSubject='all',analyzed=false,mathChecks=[];
 const disabled=()=>busy?'disabled':'';
 const photoHTML=(p,i)=>`<article class="work-photo"><div class="work-photo-image"><img src="${esc(p.preview||p.url)}" alt="Страница ${i+1}" style="${p.preview?'':`transform:rotate(${p.rotation||0}deg)`}"></div><div><strong>Страница ${i+1}</strong>${p.crop?'<small>Область выбрана</small>':''}<div class="photo-tools"><button type="button" data-photo-rotate="${i}" ${disabled()} aria-label="Повернуть страницу ${i+1}">↻ Повернуть</button><button type="button" data-photo-crop="${i}" ${disabled()}>Обрезать</button><button type="button" data-photo-remove="${i}" ${disabled()} aria-label="Убрать страницу ${i+1}">Убрать</button></div></div></article>`;
 function scanResults(){return !analyzed?'':`<section class="card scan-stage" id="recommendationsSection"><span class="eyebrow">ПРОВЕРКА ПО ПРАВИЛАМ</span><h2>Что повторить</h2><p>${state.analysisScope==='marked'?'Подбор по заданиям, которые ты отметил.':'Это темы по тексту работы. Без отметок учителя программа не определяет твои пробелы.'}</p>${mathChecks.length?`<div class="arithmetic-checks"><h3>Арифметические равенства</h3><p>Сначала сравни текст с фотографией: ошибка распознавания может изменить число или знак.</p>${mathChecks.map(x=>`<div class="arithmetic-check ${x.equal?'is-equal':'not-equal'}"><code>${esc(x.expression)}</code><span>${x.equal?'Равенство верно':`Не совпало: слева ${x.left}, справа ${x.right}`}</span></div>`).join('')}</div>`:''}${state.recommendations.length?recommendationsHtml().replace(/^<section[^>]*>|<\/section>$/g,'').replace(/<div class="eyebrow">[\s\S]*?<\/p>/,''):'<div class="scan-no-match"><h3>Уверенного совпадения с темой нет</h3><p>Проверь распознанные слова, класс и предмет. Можно открыть нужную тему вручную.</p><button class="btn btn-light" data-go="catalog">Выбрать тему</button></div>'}</section>`;}
 scan=()=>`${head('РАЗБОР РАБОТЫ','Найдём, что повторить','Добавь фотографию, проверь распознанный текст и отметь задания с ошибками.')}<div class="scan-journey" aria-label="Порядок разбора"><span><b>1</b> Фото</span><span><b>2</b> Проверка текста</span><span><b>3</b> Выбор заданий</span><span><b>4</b> Темы</span></div><div class="scan-layout"><section class="card scan-panel"><h2>1. Добавь работу</h2><p>До четырёх страниц. Лучше снять лист ровно, при хорошем освещении.</p><label class="upload-zone" for="photoInput"><strong>＋ Выбрать фото</strong><small>JPG, PNG, WEBP · до 8 МБ на страницу</small><input id="photoInput" type="file" accept="image/jpeg,image/png,image/webp" multiple ${disabled()}></label><div class="work-photos">${state.photos.map(photoHTML).join('')}</div><div class="ocr-options"><label>Язык текста<select id="ocrLanguage" ${disabled()}><option value="rus+eng" ${language==='rus+eng'?'selected':''}>Русский и английский</option><option value="rus" ${language==='rus'?'selected':''}>Русский</option><option value="eng" ${language==='eng'?'selected':''}>Английский</option></select></label><button class="btn btn-orange" id="ocrButton" ${!state.photos.length||busy?'disabled':''}>Прочитать фото</button>${busy?'<button class="btn btn-light" data-ocr-cancel>Остановить</button>':''}</div><p id="ocrStatus" class="ocr-status" role="status" aria-live="polite">${esc(message||'Фото обрабатывается на этом устройстве. ИИ-ключи и отправка фотографии на сервер не нужны.')}</p>${quality.length?`<div class="ocr-quality">${quality.map((q,i)=>`<span>Страница ${i+1}: ${q.confidence>=75?'текст читается увереннее':'нужна внимательная сверка'}${q.warnings?.length?' · '+esc(q.warnings.join(' ')):''}</span>`).join('')}</div>`:''}<div class="local-processing-note"><strong>Локальное распознавание</strong><p>Классический OCR без нейросетевого режима. Печатный текст читается лучше рукописного. Дроби, формулы, таблицы и почерк обязательно проверь.</p></div><h2>2. Проверь текст</h2><label class="field-label" for="scanText">Исправь пропущенные слова, числа и знаки</label><textarea id="scanText" class="textarea scan-text" placeholder="Здесь появится текст с фотографии. Его также можно вставить вручную.">${esc(state.scanText)}</textarea><div class="work-filters"><label>Класс<select id="workGrade">${[5,6,7,8,9].map(g=>`<option value="${g}" ${g===workGrade?'selected':''}>${g} класс</option>`).join('')}</select></label><label>Предмет<select id="workSubject"><option value="all">Все предметы</option>${C.subjects.filter(s=>s.grades.includes(workGrade)).map(s=>`<option value="${esc(s.id)}" ${s.id===workSubject?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label></div><div class="task-actions"><button class="btn btn-orange" id="splitWork" ${busy?'disabled':''}>Разделить на задания →</button><button class="btn btn-light" data-scan-example>Попробовать пример</button></div></section><aside class="card scan-help"><h2>Как получить точный разбор</h2><ol><li>Обрежь стол, края тетради и лишние надписи.</li><li>Поверни страницу, чтобы строки были горизонтальными.</li><li>Сравни текст с фото, особенно числа и математические знаки.</li><li>Отметь номера, где учитель уже нашёл ошибки.</li></ol><p>Правила подбирают возможные темы. Они не оценивают смысл сочинения и не определяют любую ошибку по одному фото.</p></aside></div>${state.scanTasks.length?scanTasksHtml():''}${scanResults()}`;
 function setMessage(s){message=s;const el=document.getElementById('ocrStatus');if(el)el.textContent=s;}
 const clearAnalysis=()=>{state.scanTasks=[];state.recommendations=[];state.marked=new Set();analyzed=false;mathChecks=[];};
 splitWork=()=>{state.scanText=document.getElementById('scanText')?.value??state.scanText;if(!state.scanText.trim()){toast('Сначала добавь текст заданий.');return;}state.scanTasks=T.split(state.scanText);state.marked=new Set();state.recommendations=[];analyzed=false;render();document.getElementById('scanTasksSection')?.scrollIntoView({behavior:'smooth'});};
 analyzeWork=()=>{const selected=state.marked.size?[...state.marked].map(i=>state.scanTasks[i]).filter(Boolean):state.scanTasks;const text=selected.join('\n');state.recommendations=T.rank(text,C.topics,workGrade,workSubject).map(x=>({id:x.id,matched:x.matched}));state.analysisScope=state.marked.size?'marked':'all';mathChecks=T.equalities(text);analyzed=true;render();document.getElementById('recommendationsSection')?.scrollIntoView({behavior:'smooth'});};
 loadOCR=()=>{if(window.Tesseract)return Promise.resolve();if(loader)return loader;loader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/ocr/tesseract.min.js';script.onload=resolve;script.onerror=()=>{loader=null;reject(new Error('Локальные файлы OCR недоступны'));};document.head.appendChild(script);});return loader;};
 async function photoCanvas(p,withCrop=true){
  const image=await createImageBitmap(p.file);const angle=(p.rotation||0)%360,scale=Math.min(2,2400/Math.max(image.width,image.height));
  const w=Math.round(image.width*scale),h=Math.round(image.height*scale),c=document.createElement('canvas');c.width=angle%180?h:w;c.height=angle%180?w:h;
  const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.translate(c.width/2,c.height/2);ctx.rotate(angle*Math.PI/180);ctx.drawImage(image,-w/2,-h/2,w,h);image.close();
  if(withCrop&&p.crop){const box=p.crop,out=document.createElement('canvas');out.width=Math.max(1,Math.round(c.width*box.w));out.height=Math.max(1,Math.round(c.height*box.h));out.getContext('2d').drawImage(c,c.width*box.x,c.height*box.y,c.width*box.w,c.height*box.h,0,0,out.width,out.height);return out;}return c;
 }
 function imageQuality(source){
  const c=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(source.width,source.height));c.width=Math.max(3,Math.round(source.width*scale));c.height=Math.max(3,Math.round(source.height*scale));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,c.width,c.height);const data=ctx.getImageData(0,0,c.width,c.height).data,g=new Float32Array(c.width*c.height);let mean=0,sum=0,sq=0,n=0,dark=0;
  for(let i=0;i<g.length;i++){g[i]=.299*data[i*4]+.587*data[i*4+1]+.114*data[i*4+2];mean+=g[i];if(g[i]<60)dark++;}mean/=g.length;
  for(let y=1;y<c.height-1;y++)for(let x=1;x<c.width-1;x++){const i=y*c.width+x,v=4*g[i]-g[i-1]-g[i+1]-g[i-c.width]-g[i+c.width];sum+=v;sq+=v*v;n++;}
  const sharpness=sq/n-(sum/n)**2,warnings=[];if(mean<100||dark/g.length>.65)warnings.push('Снимок тёмный. Добавь света.');if(sharpness<25)warnings.push('Мало чётких контуров: возможны размытие или пустая страница.');if(Math.min(source.width,source.height)<500)warnings.push('Мало пикселей. Сними страницу ближе.');return {mean,sharpness,warnings};
 }
 function variant(source,binary){
  const c=document.createElement('canvas');c.width=source.width;c.height=source.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0);const image=ctx.getImageData(0,0,c.width,c.height),data=image.data,hist=new Uint32Array(256);
  for(let i=0;i<data.length;i+=4){const v=Math.round(.299*data[i]+.587*data[i+1]+.114*data[i+2]);data[i]=data[i+1]=data[i+2]=v;hist[v]++;}
  const count=c.width*c.height;let lo=0,hi=255,total=0;for(let i=0;i<256;i++){total+=hist[i];if(total>=count*.005){lo=i;break;}}total=0;for(let i=255;i>=0;i--){total+=hist[i];if(total>=count*.005){hi=i;break;}}if(hi-lo<35){lo=0;hi=255;}
  let threshold=150;if(binary){let sum=0,bg=0,sumBg=0,best=-1;for(let i=0;i<256;i++)sum+=i*hist[i];for(let i=0;i<256;i++){bg+=hist[i];if(!bg)continue;const fg=count-bg;if(!fg)break;sumBg+=i*hist[i];const delta=sumBg/bg-(sum-sumBg)/fg,between=bg*fg*delta*delta;if(between>best){best=between;threshold=i;}}}
  for(let i=0;i<data.length;i+=4){const v=binary?(data[i]>threshold?255:0):Math.max(0,Math.min(255,(data[i]-lo)*255/(hi-lo)));data[i]=data[i+1]=data[i+2]=v;data[i+3]=255;}ctx.putImageData(image,0,0);return c;
 }
 recognizePhotos=async()=>{
  if(busy||!state.photos.length)return;document.dispatchEvent(new Event('school-photo-changed'));busy=true;stop=false;quality=[];render();setMessage('Подготавливаем классический OCR…');
  try{await loadOCR();const base=new URL('vendor/ocr/',document.baseURI);worker=await Tesseract.createWorker(language,0,{legacyCore:true,legacyLang:true,workerPath:new URL('worker.min.js',base).href,corePath:new URL('core/',base).href,langPath:new URL('lang',base).href,gzip:true,cachePath:'school-classic-ocr-v1',logger:m=>{if(m.progress&&m.status==='recognizing text')setMessage('Читаем текст: '+Math.round(m.progress*100)+'%');}});
   await worker.setParameters({tessedit_pageseg_mode:'3',user_defined_dpi:'300',preserve_interword_spaces:'1'});const parts=[];
   for(let i=0;i<state.photos.length;i++){
    if(stop)break;setMessage(`Готовим страницу ${i+1} из ${state.photos.length}…`);const source=await photoCanvas(state.photos[i]);
    const imageCheck=imageQuality(source);if(imageCheck.warnings.length)setMessage(`Страница ${i+1}: ${imageCheck.warnings.join(' ')} Пробуем прочитать.`);
    let best=(await worker.recognize(variant(source,false))).data;
    if(!stop&&(best.confidence||0)<85){setMessage(`Пробуем чёрно-белый вариант страницы ${i+1}…`);const other=(await worker.recognize(variant(source,true))).data;if((other.confidence||0)>(best.confidence||0)+2&&other.text.trim().length>=Math.min(10,best.text.trim().length))best=other;}
    quality.push({confidence:Number(best.confidence)||0,...imageCheck});parts.push((best.text||'').trim());
   }
   if(!stop){state.scanText=parts.filter(Boolean).join('\n\n');clearAnalysis();message=state.scanText?'Текст готов. Сверь его с фото, затем переходи к заданиям.':'Текст не найден. Попробуй обрезать страницу или введи текст вручную.';}
  }catch(error){message=stop?'Распознавание остановлено. Предыдущий текст сохранён.':'Не удалось прочитать фото. Проверь, что сайт запущен через локальный сервер; можно ввести текст вручную.';if(!stop)console.error(error);}
  finally{if(worker){try{await worker.terminate();}catch{}worker=null;}busy=false;if(stop)message='Распознавание остановлено. Предыдущий текст сохранён.';render();}
 };
 async function cropPhoto(index){
  const p=state.photos[index];if(!p||busy)return;const source=await photoCanvas(p,false),modal=document.createElement('div');modal.className='crop-overlay';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label','Обрезать фотографию');modal.innerHTML='<div class="crop-dialog"><h2>Выдели страницу</h2><p>Проведи по фотографии от одного угла нужной области к другому.</p><canvas class="crop-canvas" aria-label="Выделение области фотографии"></canvas><div class="task-actions"><button class="btn btn-orange" data-crop-apply>Применить</button><button class="btn btn-light" data-crop-reset>Вся страница</button><button class="btn btn-light" data-crop-close>Отмена</button></div></div>';document.body.appendChild(modal);
  const c=modal.querySelector('canvas'),ctx=c.getContext('2d');const scale=Math.min(1,700/source.width,650/source.height);c.width=source.width*scale;c.height=source.height*scale;let from=null,box=null;
  const draw=()=>{ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(source,0,0,c.width,c.height);if(box){ctx.fillStyle='#1d5a8720';ctx.fillRect(box.x,box.y,box.w,box.h);ctx.strokeStyle='#3279b3';ctx.lineWidth=3;ctx.strokeRect(box.x,box.y,box.w,box.h);}};draw();
  const point=e=>{const r=c.getBoundingClientRect();return {x:Math.max(0,Math.min(c.width,(e.clientX-r.left)*c.width/r.width)),y:Math.max(0,Math.min(c.height,(e.clientY-r.top)*c.height/r.height))};};
  c.onpointerdown=e=>{from=point(e);c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!from)return;const to=point(e);box={x:Math.min(from.x,to.x),y:Math.min(from.y,to.y),w:Math.abs(to.x-from.x),h:Math.abs(to.y-from.y)};draw();};c.onpointerup=()=>{from=null;};
  const close=()=>{document.removeEventListener('keydown',onKey);modal.remove();};const onKey=e=>{if(e.key==='Escape')close();};document.addEventListener('keydown',onKey);
  modal.querySelector('[data-crop-close]').onclick=close;
  modal.querySelector('[data-crop-reset]').onclick=async()=>{document.dispatchEvent(new Event('school-photo-changed'));p.crop=null;p.preview=(await photoCanvas(p)).toDataURL('image/jpeg',.85);close();render();};
  modal.querySelector('[data-crop-apply]').onclick=async()=>{if(!box||box.w<15||box.h<15){toast('Выдели область побольше.');return;}document.dispatchEvent(new Event('school-photo-changed'));p.crop={x:box.x/c.width,y:box.y/c.height,w:box.w/c.width,h:box.h/c.height};p.preview=(await photoCanvas(p)).toDataURL('image/jpeg',.85);close();render();};modal.querySelector('[data-crop-close]').focus();
 }
 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-ocr-cancel')){stop=true;setMessage('Останавливаем распознавание…');if(worker)await worker.terminate();worker=null;return;}
  const action=['rotate','remove','crop'].find(a=>b.hasAttribute('data-photo-'+a));if(!action||busy)return;
  const index=Number(b.dataset['photo'+action[0].toUpperCase()+action.slice(1)]),p=state.photos[index];if(!p)return;
  if(action==='crop'){await cropPhoto(index);return;}
  document.dispatchEvent(new Event('school-photo-changed'));if(action==='remove'){URL.revokeObjectURL(p.url);state.photos.splice(index,1);}else{p.rotation=((p.rotation||0)+90)%360;document.dispatchEvent(new Event('school-photo-changed'));p.crop=null;p.preview=(await photoCanvas(p)).toDataURL('image/jpeg',.85);}quality=[];message='Фото изменено. Запусти распознавание ещё раз.';render();
 });
 document.addEventListener('change',e=>{if(e.target.id==='ocrLanguage')language=e.target.value;if(e.target.id==='workGrade'){workGrade=Number(e.target.value);workSubject='all';render();}if(e.target.id==='workSubject')workSubject=e.target.value;});
 window.SCHOOL_SCAN_LOCAL={engine:'Tesseract Legacy',oem:0,cloud:false,neural:false,photoCanvas,variant};
 render();
})();
